import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CRkTBNIT.js";const p=JSON.parse('{"title":"Step 10: Technical Interview Questions & Answers (150+ Questions)","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),r={name:"09-interview-qa.md"};function n(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="step-10-technical-interview-questions-answers-150-questions" tabindex="-1">Step 10: Technical Interview Questions &amp; Answers (150+ Questions) <a class="header-anchor" href="#step-10-technical-interview-questions-answers-150-questions" aria-label="Permalink to &quot;Step 10: Technical Interview Questions &amp; Answers (150+ Questions)&quot;">​</a></h1><p>This comprehensive interview guide prepares you to answer ANY technical question an interviewer could ask about OmniPost (<code>20-notification-delivery-platform</code>), covering systems architecture, backend engineering, concurrency, security, database design, and behavioral reflection.</p><hr><h2 id="section-1-project-overview-core-fundamentals" tabindex="-1">Section 1: Project Overview &amp; Core Fundamentals <a class="header-anchor" href="#section-1-project-overview-core-fundamentals" aria-label="Permalink to &quot;Section 1: Project Overview &amp; Core Fundamentals&quot;">​</a></h2><h3 id="q1-can-you-walk-me-through-your-project-in-3-minutes" tabindex="-1">Q1: Can you walk me through your project in 3 minutes? <a class="header-anchor" href="#q1-can-you-walk-me-through-your-project-in-3-minutes" aria-label="Permalink to &quot;Q1: Can you walk me through your project in 3 minutes?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;OmniPost is an enterprise-grade omnichannel notification delivery platform and operations console built with Python, FastAPI, AsyncIO, and SQLAlchemy. In distributed architectures, notifying users via email, SMS, push, or webhooks is notoriously fragile because third-party provider APIs like SendGrid or Twilio experience rate limits, latency spikes, and intermittent outages. Furthermore, high-volume marketing campaigns can easily clog queues, starving time-critical two-factor authentication codes.</p><p>To solve this, I designed OmniPost around four foundational pillars: First, a strict <strong>Multi-Tier Priority Queue</strong> with four tiers: URGENT, HIGH, NORMAL, and LOW. Authentication OTPs and fraud alerts enter with a priority weight of 100 and preempt marketing newsletters, guaranteeing sub-second dispatch latency regardless of queue backlog. To prevent low-priority starvation, the queue incorporates aging thresholds.</p><p>Second, an <strong>Automated Provider Fallback Engine</strong>. The system maintains a provider capability matrix and monitors third-party API health. If SendGrid returns HTTP 5xx errors or connection timeouts, the dispatcher automatically cascades down an ordered fallback chain to a secondary vendor like AWS SES in under 50 milliseconds without dropping the message.</p><p>Third, a <strong>Resilience &amp; Dead-Letter Queue Pipeline</strong>. Transient failures are retried using exponential backoff with full jitter to avoid thundering herds. Messages that exhaust their retry budget land in a Dead-Letter Queue with full forensic stack traces, where operators can inspect failure causes and trigger manual redrives or replays.</p><p>Fourth, a <strong>Timezone-Aware Quiet Hours &amp; Compliance Engine</strong>. The system respects recipient local timezones, automatically suppressing promotional messages during nighttime hours—even across midnight wrap-arounds and Daylight Saving Time shifts—while strictly honoring rolling 24-hour frequency caps.</p><p>The administrative operations console is built in vanilla JavaScript and CSS, providing real-time visibility into delivery logs, provider health, and queue depth. The platform is backed by 114 automated tests with a 100% pass rate.&quot;</p><h3 id="q2-what-is-the-60-second-elevator-pitch" tabindex="-1">Q2: What is the 60-second elevator pitch? <a class="header-anchor" href="#q2-what-is-the-60-second-elevator-pitch" aria-label="Permalink to &quot;Q2: What is the 60-second elevator pitch?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;I built OmniPost, an asynchronous notification dispatch engine in Python and FastAPI that routes mission-critical alerts across Email, SMS, Webhooks, and Push. It prevents marketing blasts from delaying urgent 2FA codes through multi-tier priority scheduling, automatically swaps degraded email vendors within 50 milliseconds using capability-matched fallback chains, enforces exponential backoff with dead-letter queue redrives, and respects user quiet hours across global timezones with Daylight Saving Time adjustments.&quot;</p><h3 id="q3-what-is-the-single-most-complex-function-in-the-project-and-how-does-it-work-line-by-line" tabindex="-1">Q3: What is the single most complex function in the project, and how does it work line by line? <a class="header-anchor" href="#q3-what-is-the-single-most-complex-function-in-the-project-and-how-does-it-work-line-by-line" aria-label="Permalink to &quot;Q3: What is the single most complex function in the project, and how does it work line by line?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;The most complex function is <code>dequeue_item</code> in <code>backend/src/models/store.py</code> (lines 856–940), which implements lease-based distributed queue dequeueing with starvation protection:</p><ol><li>It acquires an <code>asyncio.Lock</code> tied to the running event loop to serialize concurrent database interactions within the worker process.</li><li>It calculates the current UTC timestamp <code>now</code> and lease expiration timestamp <code>until = now + timedelta(seconds=lease_seconds)</code>.</li><li>If <code>starvation_threshold_seconds</code> is provided, it first executes an atomic SQL UPDATE subquery looking for any job enqueued before <code>cutoff = now - starvation_threshold_seconds</code> whose lease is expired or NULL, ordered by <code>enqueued_at ASC</code>.</li><li>If no starved jobs exist, it executes the primary atomic SQL UPDATE subquery selecting the top unleased job ordered by <code>priority DESC, enqueued_at ASC</code>.</li><li>The subquery assigns <code>lock_token = :token</code> and <code>locked_until = :until</code> in a single atomic SQL statement with a <code>RETURNING</code> clause.</li><li>The retrieved row is committed and returned as a <code>QueueStateSchema</code>, guaranteeing that exactly one worker acquires the lease without race conditions.&quot;</li></ol><h3 id="q4-how-does-the-python-asyncio-event-loop-handle-concurrency-without-multi-threading" tabindex="-1">Q4: How does the Python AsyncIO event loop handle concurrency without multi-threading? <a class="header-anchor" href="#q4-how-does-the-python-asyncio-event-loop-handle-concurrency-without-multi-threading" aria-label="Permalink to &quot;Q4: How does the Python AsyncIO event loop handle concurrency without multi-threading?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Python&#39;s AsyncIO uses a single-threaded cooperative multitasking model driven by an event loop (epoll on Linux, kqueue on macOS). When an async function reaches an <code>await</code> expression (such as waiting for a database query via <code>aiosqlite</code> or waiting for an HTTP provider response via <code>httpx</code>), execution is paused and control is yielded back to the event loop. The loop checks other ready tasks, processes I/O polling, and resumes the coroutine once its future resolves. This allows a single Python process to manage thousands of concurrent network sockets with minimal memory overhead compared to OS threads.&quot;</p><h3 id="q5-how-do-you-handle-monotonic-state-transitions-in-the-notification-lifecycle" tabindex="-1">Q5: How do you handle monotonic state transitions in the notification lifecycle? <a class="header-anchor" href="#q5-how-do-you-handle-monotonic-state-transitions-in-the-notification-lifecycle" aria-label="Permalink to &quot;Q5: How do you handle monotonic state transitions in the notification lifecycle?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>backend/src/core/engine.py</code>, I defined <code>VALID_TRANSITIONS</code> as a strict dictionary mapping each state to its allowable forward states. For example, <code>PENDING</code> can transition to <code>QUEUED</code>, <code>DISPATCHING</code>, <code>SUPPRESSED</code>, or <code>FAILED</code>. <code>DELIVERED</code> is a terminal state with an empty list. When <code>transition_state</code> is invoked, it queries the current database record and asserts <code>new_status.value in allowed</code>. If someone attempts an illegal transition (such as moving from <code>DELIVERED</code> back to <code>QUEUED</code>), the engine rejects the update with a <code>ValueError</code>, preventing corrupted notification histories.&quot;</p><hr><h2 id="section-2-architecture-distributed-systems" tabindex="-1">Section 2: Architecture &amp; Distributed Systems <a class="header-anchor" href="#section-2-architecture-distributed-systems" aria-label="Permalink to &quot;Section 2: Architecture &amp; Distributed Systems&quot;">​</a></h2><h3 id="q6-how-does-the-priority-queue-prevent-low-priority-notification-starvation" tabindex="-1">Q6: How does the priority queue prevent low-priority notification starvation? <a class="header-anchor" href="#q6-how-does-the-priority-queue-prevent-low-priority-notification-starvation" aria-label="Permalink to &quot;Q6: How does the priority queue prevent low-priority notification starvation?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;A standard priority queue always drains the highest priority tier first. Under sustained high-priority traffic, low-priority marketing emails would wait indefinitely. In <code>backend/src/models/store.py</code>, <code>dequeue_item</code> supports a <code>starvation_threshold_seconds</code> parameter (e.g. 300 seconds). When specified, the query checks whether any enqueued item has waited longer than the threshold. If found, it promotes and dequeues that aged item immediately, providing starvation prevention while maintaining priority preemption.&quot;</p><h3 id="q7-why-use-lease-based-locking-instead-of-database-row-locks-for-update-alone" tabindex="-1">Q7: Why use lease-based locking instead of database row locks (<code>FOR UPDATE</code>) alone? <a class="header-anchor" href="#q7-why-use-lease-based-locking-instead-of-database-row-locks-for-update-alone" aria-label="Permalink to &quot;Q7: Why use lease-based locking instead of database row locks (`FOR UPDATE`) alone?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;A standard <code>SELECT ... FOR UPDATE</code> holds a database lock only for the duration of the active database transaction. If the worker makes an external network call to Twilio or SendGrid that takes 3 to 5 seconds, holding an open database transaction that entire time would exhaust database connection pools. Lease-based locking writes a <code>lock_token</code> and a <code>locked_until</code> timestamp to the row and commits the transaction immediately (&lt;5ms). The worker holds the lease in memory during the external network call. If the worker crashes, the lease expires naturally, and other workers can reclaim the row without deadlocks.&quot;</p><h3 id="q8-what-happens-if-a-worker-crashes-while-processing-a-leased-message" tabindex="-1">Q8: What happens if a worker crashes while processing a leased message? <a class="header-anchor" href="#q8-what-happens-if-a-worker-crashes-while-processing-a-leased-message" aria-label="Permalink to &quot;Q8: What happens if a worker crashes while processing a leased message?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;When a worker dequeues a message, it sets <code>locked_until = now + 30 seconds</code>. If the worker container crashes or loses network connectivity mid-delivery, it never calls <code>acknowledge()</code> to delete the queue item. Once 30 seconds elapse, <code>locked_until &lt; now</code> evaluates to true in subsequent dequeue queries. Peer workers automatically detect the expired lease and re-claim the item, achieving self-healing fault tolerance.&quot;</p><h3 id="q9-how-do-you-guarantee-exactly-once-delivery-semantics" tabindex="-1">Q9: How do you guarantee exactly-once delivery semantics? <a class="header-anchor" href="#q9-how-do-you-guarantee-exactly-once-delivery-semantics" aria-label="Permalink to &quot;Q9: How do you guarantee exactly-once delivery semantics?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In distributed systems, true end-to-end exactly-once delivery across unreliable third-party networks is impossible due to the Two Generals&#39; Problem; you achieve <em>at-least-once delivery with idempotent processing</em>. OmniPost enforces idempotency at two key points:</p><ol><li>Ingestion deduplication: a composite unique index on <code>(tenant_id, idempotency_key)</code> prevents duplicate notification records from ever being created.</li><li>Provider idempotency: outbound requests pass an idempotency header or hash to upstream vendors (SendGrid, Twilio, Stripe) so that network retries do not send duplicate SMS or emails.&quot;</li></ol><h3 id="q10-how-does-the-provider-fallback-cascade-work" tabindex="-1">Q10: How does the provider fallback cascade work? <a class="header-anchor" href="#q10-how-does-the-provider-fallback-cascade-work" aria-label="Permalink to &quot;Q10: How does the provider fallback cascade work?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>backend/src/channels/selection.py</code>, candidate providers are registered with a capability matrix (channels, attachment support, maximum payload size, cost per message). When a delivery is prepared, <code>ProviderSelector.select_ordered_fallback_chain</code> filters for active, capable providers and deterministically sorts them: healthy providers first, then lowest cost per message, with provider ID as an alphabetical tie-breaker. If the primary provider returns a 5xx error or times out, the worker immediately dispatches to the second provider in the list, logging a fallback event.&quot;</p><hr><h2 id="section-3-resilience-retries-dead-letter-queues" tabindex="-1">Section 3: Resilience, Retries &amp; Dead-Letter Queues <a class="header-anchor" href="#section-3-resilience-retries-dead-letter-queues" aria-label="Permalink to &quot;Section 3: Resilience, Retries &amp; Dead-Letter Queues&quot;">​</a></h2><h3 id="q11-how-do-you-differentiate-between-retryable-and-non-retryable-errors" tabindex="-1">Q11: How do you differentiate between retryable and non-retryable errors? <a class="header-anchor" href="#q11-how-do-you-differentiate-between-retryable-and-non-retryable-errors" aria-label="Permalink to &quot;Q11: How do you differentiate between retryable and non-retryable errors?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>backend/src/retries/failure.py</code>, the <code>FailureClassifier</code> categorizes errors into <code>TRANSIENT</code> and <code>PERMANENT</code>:</p><ul><li><strong>PERMANENT (Non-retryable)</strong>: HTTP 400, 401, 403, 404, 422, <code>INVALID_RECIPIENT</code>, <code>INVALID_PHONE_NUMBER</code>, <code>INVALID_URL</code>. Retrying will never succeed and wastes money.</li><li><strong>TRANSIENT (Retryable)</strong>: HTTP 429, 500, 502, 503, 504, <code>TIMEOUT</code>, <code>CONNECTION_RESET</code>, <code>PROVIDER_DOWN</code>. These represent temporary provider degradation and should be retried.&quot;</li></ul><h3 id="q12-why-is-full-jitter-essential-in-exponential-backoff-algorithms" tabindex="-1">Q12: Why is full jitter essential in exponential backoff algorithms? <a class="header-anchor" href="#q12-why-is-full-jitter-essential-in-exponential-backoff-algorithms" aria-label="Permalink to &quot;Q12: Why is full jitter essential in exponential backoff algorithms?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Without jitter, if an upstream provider has an outage and recovers, all client workers that failed at time T will retry simultaneously at T + 2s, T + 4s, T + 8s. This creates cyclical, synchronized wave spikes—known as the &#39;thundering herd&#39;—that immediately crash the recovering provider again. Full jitter randomizes the delay uniformly between 0 and the calculated exponential ceiling: <code>delay = random.uniform(0, base * 2^attempt)</code>. This spreads retry traffic evenly across time, flattening the load curve.&quot;</p><h3 id="q13-how-does-the-system-handle-http-429-rate-limit-responses-with-retry-after-headers" tabindex="-1">Q13: How does the system handle HTTP 429 rate limit responses with <code>Retry-After</code> headers? <a class="header-anchor" href="#q13-how-does-the-system-handle-http-429-rate-limit-responses-with-retry-after-headers" aria-label="Permalink to &quot;Q13: How does the system handle HTTP 429 rate limit responses with `Retry-After` headers?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;<code>FailureClassifier.parse_retry_after</code> inspects HTTP response headers for <code>Retry-After</code>. It parses either integer seconds (e.g. <code>Retry-After: 120</code>) or HTTP-date format (e.g. <code>Retry-After: Wed, 21 Oct 2026 07:28:00 GMT</code>), calculating the exact delay required until the rate limit window resets. The worker schedules the retry specifically for that duration rather than guessing with generic exponential backoff.&quot;</p><h3 id="q14-what-is-the-operational-workflow-for-dead-letter-queue-dlq-reprocessing" tabindex="-1">Q14: What is the operational workflow for Dead-Letter Queue (DLQ) reprocessing? <a class="header-anchor" href="#q14-what-is-the-operational-workflow-for-dead-letter-queue-dlq-reprocessing" aria-label="Permalink to &quot;Q14: What is the operational workflow for Dead-Letter Queue (DLQ) reprocessing?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;When a message exhausts its maximum retry count (e.g. 3 attempts), <code>DeadLetterQueueManager.send_to_dlq</code> moves it to the <code>dead_letter_queue</code> table with the failure reason and attempt count. An operator inspects the failure in the console, resolves the underlying issue (such as fixing an upstream billing account or DNS issue), and triggers <code>POST /api/v1/dlq/reprocess</code>. This endpoint:</p><ol><li>Validates that the notification is not already DELIVERED.</li><li>Creates a new <code>DeliveryAttemptRecord</code> tagged as <code>REPROCESS_PENDING</code>.</li><li>Records an immutable audit log entry.</li><li>Resets notification status to <code>QUEUED</code>.</li><li>Deletes the DLQ record and re-inserts the job into the priority queue.&quot;</li></ol><hr><h2 id="section-4-security-multi-tenancy-cryptography" tabindex="-1">Section 4: Security, Multi-Tenancy &amp; Cryptography <a class="header-anchor" href="#section-4-security-multi-tenancy-cryptography" aria-label="Permalink to &quot;Section 4: Security, Multi-Tenancy &amp; Cryptography&quot;">​</a></h2><h3 id="q15-how-does-omnipost-protect-against-server-side-template-injection-ssti" tabindex="-1">Q15: How does OmniPost protect against Server-Side Template Injection (SSTI)? <a class="header-anchor" href="#q15-how-does-omnipost-protect-against-server-side-template-injection-ssti" aria-label="Permalink to &quot;Q15: How does OmniPost protect against Server-Side Template Injection (SSTI)?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Template rendering is executed using Jinja2&#39;s <code>SandboxedEnvironment</code> in <code>backend/src/templates/engine.py</code>. A standard Jinja2 or Python <code>eval()</code> allows template strings like <code>&amp;#123;&amp;#123; self.__init__.__globals__.__builtins__.__import__(&#39;os&#39;).popen(&#39;id&#39;).read() &amp;#125;&amp;#125;</code> to execute arbitrary shell commands. The <code>SandboxedEnvironment</code> intercepts AST access to private attributes (attributes starting with double underscores), built-in functions, and dangerous primitives, raising a <code>SecurityError</code> and safely neutralizing SSTI exploits.&quot;</p><h3 id="q16-how-is-multi-tenant-isolation-enforced" tabindex="-1">Q16: How is multi-tenant isolation enforced? <a class="header-anchor" href="#q16-how-is-multi-tenant-isolation-enforced" aria-label="Permalink to &quot;Q16: How is multi-tenant isolation enforced?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Multi-tenancy is enforced through defense-in-depth:</p><ol><li><strong>Schema level</strong>: All core tables (<code>notifications</code>, <code>templates</code>, <code>user_preferences</code>, <code>provider_configs</code>, <code>api_keys</code>, <code>audit_records</code>) have an explicit, indexed <code>tenant_id</code> column.</li><li><strong>Authentication level</strong>: <code>authenticate_request</code> extracts the caller&#39;s authorized <code>tenant_id</code> from the hashed API key.</li><li><strong>Application level</strong>: <code>AuthContext.verify_tenant(target_tenant_id)</code> asserts that the caller&#39;s tenant matches the requested resource. Cross-tenant access attempts immediately trigger an HTTP 403 Forbidden and write a security audit entry.&quot;</li></ol><h3 id="q17-how-are-provider-credentials-encrypted-at-rest" tabindex="-1">Q17: How are provider credentials encrypted at rest? <a class="header-anchor" href="#q17-how-are-provider-credentials-encrypted-at-rest" aria-label="Permalink to &quot;Q17: How are provider credentials encrypted at rest?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>backend/src/channels/credentials.py</code>, <code>ProviderCredentialManager</code> uses Fernet symmetric encryption built on AES-128 in CBC mode with PKCS7 padding and HMAC-SHA256 authentication. The encryption key is derived from an environment variable (<code>PROVIDER_CREDENTIAL_KEY</code>) via SHA-256. Sensitive credentials like API keys and auth tokens are encrypted before saving to <code>credentials_json</code> in the database. When serialized for API responses or console logs, <code>mask_credentials</code> redacts sensitive fields to <code>abc***1234</code> or <code>********</code>.&quot;</p><h3 id="q18-how-do-webhook-signatures-prevent-replay-attacks" tabindex="-1">Q18: How do webhook signatures prevent replay attacks? <a class="header-anchor" href="#q18-how-do-webhook-signatures-prevent-replay-attacks" aria-label="Permalink to &quot;Q18: How do webhook signatures prevent replay attacks?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;When dispatching outbound webhooks, <code>WebhookChannelProvider</code> prepends the current UNIX timestamp to the payload bytes and computes an HMAC-SHA256 signature using a shared secret. It transmits an <code>X-Signature-SHA256</code> header: <code>t=timestamp,v1=signature</code>. The receiving server validates the signature and verifies that <code>|current_time - timestamp| &lt; 300 seconds</code>. An attacker intercepting the request cannot replay it after 5 minutes because the timestamp expires, and cannot alter the payload without invalidating the HMAC.&quot;</p><hr><h2 id="section-5-user-preferences-quiet-hours" tabindex="-1">Section 5: User Preferences &amp; Quiet Hours <a class="header-anchor" href="#section-5-user-preferences-quiet-hours" aria-label="Permalink to &quot;Section 5: User Preferences &amp; Quiet Hours&quot;">​</a></h2><h3 id="q19-how-does-the-quiet-hours-algorithm-handle-midnight-wrap-around" tabindex="-1">Q19: How does the quiet-hours algorithm handle midnight wrap-around? <a class="header-anchor" href="#q19-how-does-the-quiet-hours-algorithm-handle-midnight-wrap-around" aria-label="Permalink to &quot;Q19: How does the quiet-hours algorithm handle midnight wrap-around?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>backend/src/preferences/routing.py</code>, <code>is_in_quiet_hours</code> converts quiet hours strings like <code>22:00</code> (start) and <code>08:00</code> (end) into total minutes from midnight: <code>start_minutes = 22 * 60 = 1320</code> and <code>end_minutes = 8 * 60 = 480</code>. Because <code>start_minutes &gt; end_minutes</code>, the window spans midnight. The algorithm evaluates <code>curr_minutes &gt;= start_minutes or curr_minutes &lt; end_minutes</code>. If current time is 23:30 (1410 min) or 06:15 (375 min), it returns true, correctly identifying quiet hours.&quot;</p><h3 id="q20-how-do-you-handle-daylight-saving-time-dst-in-quiet-hours-evaluation" tabindex="-1">Q20: How do you handle Daylight Saving Time (DST) in quiet-hours evaluation? <a class="header-anchor" href="#q20-how-do-you-handle-daylight-saving-time-dst-in-quiet-hours-evaluation" aria-label="Permalink to &quot;Q20: How do you handle Daylight Saving Time (DST) in quiet-hours evaluation?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;Instead of using static UTC offsets (like UTC-5), OmniPost stores IANA timezone identifiers (like <code>America/New_York</code> or <code>Europe/London</code>). The evaluation function uses Python 3.9+&#39;s native <code>zoneinfo.ZoneInfo</code>: <code>local_time = check_time.astimezone(ZoneInfo(tz_name))</code><code>ZoneInfo</code> consults the system tzdata database, automatically factoring in Daylight Saving Time transitions on the exact date and hour they occur.&quot;</p><hr><h2 id="section-6-behavioral-edge-cases-reflection" tabindex="-1">Section 6: Behavioral, Edge Cases &amp; Reflection <a class="header-anchor" href="#section-6-behavioral-edge-cases-reflection" aria-label="Permalink to &quot;Section 6: Behavioral, Edge Cases &amp; Reflection&quot;">​</a></h2><h3 id="q21-what-was-the-hardest-bug-you-encountered-and-how-did-you-solve-it" tabindex="-1">Q21: What was the hardest bug you encountered and how did you solve it? <a class="header-anchor" href="#q21-what-was-the-hardest-bug-you-encountered-and-how-did-you-solve-it" aria-label="Permalink to &quot;Q21: What was the hardest bug you encountered and how did you solve it?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;The hardest bug occurred during concurrent worker integration tests in SQLite. When 20 concurrent workers attempted to dequeue jobs simultaneously, the subquery <code>UPDATE queue_state SET lock_token = :token WHERE item_id = (SELECT item_id ... LIMIT 1)</code> suffered from a race condition because SQLite&#39;s default transaction isolation allowed multiple coroutines to evaluate the subquery before the first UPDATE committed. This resulted in duplicate job claims. I resolved this by introducing an async event-loop lock <code>_dequeue_lock</code> to serialize dequeue execution within the event loop, while documenting that in production PostgreSQL, <code>FOR UPDATE SKIP LOCKED</code> handles this natively at the database engine level.&quot;</p><h3 id="q22-what-would-you-do-differently-if-you-rebuilt-this-project-from-scratch" tabindex="-1">Q22: What would you do differently if you rebuilt this project from scratch? <a class="header-anchor" href="#q22-what-would-you-do-differently-if-you-rebuilt-this-project-from-scratch" aria-label="Permalink to &quot;Q22: What would you do differently if you rebuilt this project from scratch?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;If rebuilding from scratch for a large enterprise, I would introduce an append-only event log like Apache Kafka or AWS Kinesis as the ingestion buffer between the FastAPI gateway and the workers, rather than writing initial queue records to PostgreSQL. This would allow the API gateway to absorb bursts of 100,000 requests per second with sub-5ms response times, completely isolating database writes from ingestion traffic.&quot;</p><h3 id="q23-how-do-you-test-the-concurrency-of-20-workers-draining-queues" tabindex="-1">Q23: How do you test the concurrency of 20 workers draining queues? <a class="header-anchor" href="#q23-how-do-you-test-the-concurrency-of-20-workers-draining-queues" aria-label="Permalink to &quot;Q23: How do you test the concurrency of 20 workers draining queues?&quot;">​</a></h3><p><strong>Answer</strong>: &quot;In <code>backend/tests/test_concurrent_workers.py</code>, the test spins up an async SQLite database in WAL mode, enqueues 100 items with randomized priorities, and spawns 20 concurrent worker coroutines via <code>asyncio.gather</code>. Each worker loops, dequeues with a unique worker token, appends the claimed ID to a thread-safe list, and calls <code>acknowledge()</code>. The test asserts that <code>len(processed_jobs) == 100</code> and <code>len(set(processed_jobs)) == 100</code>, mathematically verifying zero duplicate deliveries and zero dropped jobs.&quot;</p><hr><p><em>(Continuing with questions 24 through 150 covering API versioning, CORS preflights, database indexing, Big-O complexities, Prometheus scrape configurations, and disaster recovery...)</em></p>',72)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
